def expected_presidents(T, n):
    """Calculates the expected number of presidents Devupur can select in their upcoming election."""
    if n == 1:
        return 1
    # The expected number of presidents is sum of binomial coefficients C(n, k) for k ranging from 0 to n-2, each multiplied by (sum of reciprocals of binomial coefficients starting from k to n)
    return sum(binomial_coefficient(n, k) * sum(1 / binomial_coefficient(n, j) for j in range(k, n)) for k in range(1, n-1))

def binomial_coefficient(n, k):
    """Calculates the binomial coefficient C(n, k) using factorial."""
    return factorial(n) // (factorial(k) * factorial(n - k))

