from collections import defaultdict, deque

def find_min_sparrows(n, m, classes):
    graph = defaultdict(list)
    for i in range(1, n+1):
        assert classes[i] in {1, 2, 3}
    for u, v in zip(range(1, n+1), range(1, n+1)):
        if classes[u] != classes[v]:
            raise NameError("Classes mismatch")
        graph[classes[u]].append(v)
    visited = [False] * (n+1)
    dfs_stack = deque()
    for i in range(1, n+1):
        if not visited[i]:
            dfs_stack.append(i)
            while dfs_stack:
                u = dfs_stack.pop()
                visited[u] = True
                dfs_stack.extend(graph[u])
    if not all(visited):
        return -1

    class_count = [0] * 3
    for i in range(1, n+1):
        if classes[i] == 1:
            class_count[0] += 1
        elif classes[i] == 2:
            class_count[1] += 1
        elif classes[i] == 3:
            class_count[2] += 1

    def dfs(u, g, s, c):
        if visited[u]:
            return
        visited[u] = True
        for v in g[u]:
            if visited[v] and c + 1 > 2 or not s[v]:
                return
            dfs(v, g, s, c+1)

    result = 0
    for i in range(1, n+1):
        if classes[i] == 1:
            if not s[i]:
                s[i] = True
                result += 1
        else:
            g = defaultdict(list)
            for v in graph[i]:
                g[i].append(v)
            for v in graph[v]:
                dfs(v, g, s, 0)
    return result

# Example usage
