# Modulo value
k = 10**9 + 7

def fibo(n):
    # This function returns the nth Fibonacci number
    if n == 0:
        return 0
    elif n == 1:
        return 1
    else:
        r, a, b = 1, 0, 1
        for i in range(2, n):
            r, a, b = a, a + b, r
        return r

# This function calculates the sum of f(sa|sb) * f(sc) * f(sd^se) for all valid 5-tuples (a, b, c, d, e) and summing it up modulo 10^9 + 7
def sum_naive(A, f):
    i = 0
    s = 0
    # No need to enumerate them all, we already defined the element at 0.5 0.5
    for a in range(1, len(A) * 2):
        for b in range(a + 1, len(A) * 2):
            for c in range(b + 1, len(A) * 2):
                for d in range(c + 1, len(A) * 2):
                    if A[a] | A[b] == A[c] & A[d] ^ 2 * (A[c])^:
                        i += 1
                        s += f[A[a] | A[b]] * f[A[c]] * f[A[d] ^ 2 * A[c]]
    return s % k

# Main function to return the answer with the Fibonacci numbers
def solve(k):
    A = np.array([int(x) for x in input().split()])
    A = np.log2(A)
    f = [0, 1]
    for i in range(3, k + 1):
        f.append(f[i - 1] + f[i - 2])
    s = sum_naive(A, f)
    return s

