import collections

class LCA:
    def __init__(self, N):
        self.parents = {i: [] for i in range(1, N+1)}
        for u, v in [(1, 2), (2, 3), (1, 4)]:
            self.parents[u].append(v)
            self.parents[v].append(u)

        self.heap = collections.deque([1])

        while self.heap:
            node = self.heap.popleft()
            for child in self.parents[node]:
                if child != 1:
                    self.heap.append(child)
                    self.parents[child].remove(node)
                    if not self.parents[child]:
                        self.parents.pop(child)
                    self.parents[child].append(node)

        self.inv = {child: node for node, children in self.parents.items() for child in children}

    def query(self, r, u, v):
        if u == v:
            return u
        path = self.path(r, u)
        for i in range(len(path)-1, 0, -1):
            u = path[i]
            if u != v:
                return path[i-1]

    def path(self, node, target):
        if node == target or not self.parents[node]:
            return [node]
        path = self.path(self.parents[node][0], target)
        path.append(node)
        return path

