from collections import deque

def reorder_sequence(N, K, sequence):
    # Create an undirected graph
    graph = {i: [] for i in range(N)}
    for i in range(N):
        for j in range(i+1, N):
            if abs(sequence[i] - sequence[j]) <= K:
                graph[i].append(j)
                graph[j].append(i)

    # Initialize the queue for BFS and dictionaries for distances and visited nodes
    queue = deque([i for i in range(N) if not graph[i]])
    distances = {i: float('inf') for i in range(N)}
    visited = {i: False for i in range(N)}
    distances[i] = 0

    # Perform BFS to find strongly connected components
    while queue:
        curr = queue.popleft()
        for node in graph[curr]:
            if visited[node]:
                continue
            visited[node] = True
            distances[node] = min(distances[node], distances[curr] + 1)
            queue.append(node)

    strongly_connected_components = [set() for _ in range(N)]
    for start, end in enumerate(sorted(graph)):
        visited = [False] * N
        if distances[end] > 0:
            queue = deque([end])
            visited[end] = True
            while queue:
                curr = queue.popleft()
                for node in graph[curr]:
                    if visited[node]:
                        continue
                    visited[node] = True
                    queue.append(node)

            strongly_connected_components[start] = {node for node in range(N) if visited[node] and node != start}

    # Adjust the components size to fit the sequence length
    for i, component in enumerate(strongly_connected_components):
        strongly_connected_components[i] = {seq["value"] for seq in [seq for seq in component if distances[seq["value"]] <= N]}

    # Check if any strongly connected component with size N can cover the sequence
    for component in strongly_connected_components:
        if len(component) == N:
            B = sorted(component)
            # Possible if there are enough 'K' so that we can form a sequence
            if sum(B[i+1] - B[i] for i in range(len(B)-1)) <= (N - K) * K:
                return "YES " + " ".join(map(str, B)), 1
            else:
                return "NO", 0
    return "NO", 0

T = int(input())
for _ in range(T):
    N, K = map(int, input().split())
    sequence = list(map(int, input().split()))
    print("YES " + " ".join(map(str, B)), "NO")[reorder_sequence(N, K, sequence) == (1, "YES", 0)]
