from typing import List

class UnionFind:
    def __init__(self, n):
        self.parent = list(range(n))

    def find(self, x):
        if x != self.parent[x]:
            self.parent[x] = self.find(self.parent[x])
        return self.parent[x]

    def union(self, x, y):
        root_x = self.find(x)
        root_y = self.find(y)
        if root_x != root_y:
            self.parent[root_y] = root_x

    def get_components(self):
        counter = 0
        for i in range(len(self.parent)):
            if self.parent[i] == i:
                counter += 1
        return counter

class Solution:
    def dfs(self, graph: List[List[int]], u, visited, component):
        visited[u] = True
        component.append(u)
        for v in graph[u]:
            if not visited[v]:
                self.dfs(graph, v, visited, component)

    def is_good(self, graph, start):
        visited = [False] * len(graph)
        component = []
        self.dfs(graph, start, visited, component)
        return len(component) == len(graph) - 1

    def determine_good_vertices(self, updates: List[List[int]]) -> List[int]:
        updated_graph = [[0 for _ in range(len(self.graph))] for _ in range(len(graph))]
        for u, v in updates:
            if updated_graph[u][v] == -1 or updated_graph[v][u] == -1:
                updated_graph[u][v] = 1
                updated_graph[v][u] = 1
            else:
                updated_graph[u][v] = updated_graph[v][u] = 0

        components = 0
        trees = []
        visited = [False] * len(graph)
        for i in range(len(graph)):
            if not visited[i]:
                component = []
                self.dfs(graph, i, visited, component)
                components += 1
                trees.append(component)

        good_vertices = []
        for component in trees:
            if self.is_good(updated_graph, component[0]):
                good_vertices.append(1)
            elif len(component) != 2:
                good_vertices.append(0)
            else:
                good_vertices.append(1)

        for i in range(len(updates)):
            if updated_graph[updates[i][0]][updates[i][1]] == 1:
                good_vertices[i] = 1
            else:
                good_vertices[i] = 0

        return good_vertices

