MOD = 10**9 + 7

class Operand:
    def __init__(self, i, bits):
        self.value = 1
        for j in range(i, i + bits):
            self.value = (self.value << 1) % MOD

    def reduce(self, value):
        return (value - self.value) % MOD

class Node:
    def __init__(self):
        self.opp = defaultdict(int)
        self.opp_val = defaultdict(int)

    def insert(self, i, j, bits):
        if bits == 0:
            self.opp_val[Operand(i, bits)] = [j]
            return
        self.insert(i + 1, j, bits / 2)
        if self.opp_val[Operand(i, bits/2)].count(j) == 0:
            self.opp_val[Operand(i, bits/2)].append(j)
            self.opp[(i, bits / 2)]['l'] = j
        self.insert(i + 1, j, bits / 2)
        if self.opp_val[Operand(i, bits/2)].count(j) == 1:
            self.opp_val[Operand(i, bits/2)].append(j)
            self.opp[(i, bits / 2)]['r'] = j
        else:
            self.opp[Operand(i, bits / 2)].pop()

def fib(n):
    if n == 0: return 0
    a = Node()
    for i in range(n):
        a.insert(i, 0, 0)
        a.insert(i, 1, 0)
        for j in a.opp_val:
            a.insert(j.value, i, 1)
    return a.opp_val[Operand(0, n)]


