import math
from functools import lru_cache

# Function to calculate expected number of consensuses
@lru_cache(maxsize=None)
def expected_consensus(houses, candidates):
    if houses <= 1:
        return 1

    solutions = set()
    for i in range(1, candidates + 1):
        for j in range(i, candidates + 1):
            if i == j or not i < houses and i > 0 or not j < houses + j - i and j > 0:
                continue
            cons = 1 - expected_consensus(houses - j, candidates - i + j) - expected_consensus(houses - i, candidates - j + i)
            solutions.add(cons)

    return sum(solutions) / len(solutions)

