class Graph:
    def __init__(self, num_vertices):
        self.adj_list = [[] for _ in range(num_vertices)]
        self.visited = [False] * num_vertices
        self.parent = [-1] * num_vertices
        self.min_cost = 0

    def add_edge(self, u, v):
        self.adj_list[u].append(v)
        self.adj_list[v].append(u)

    def find_parent(self, u):
        if self.parent[u] == -1:
            return u
        else:
            return self.find_parent(self.parent[u])

    def union_by_height(self, u, v):
        root_u = self.find_parent(u)
        root_v = self.find_parent(v)
        if root_u == root_v:
            return False
        if self.height[root_u] < self.height[root_v]:
            root_u = root_v
        self.parent[root_v] = root_u
        self.height[root_u] += self.height[root_v]
        return True

    def kruskal_mst(self):
        self.min_cost = 0
        for i in range(len(self.adj_list)):
            self.visited[i] = False
            self.parent[i] = -1
        Mst_Found = False
        for i in range(len(self.adj_list)):
            if i not in self.visited and not Mst_Found:
                u = self.find_parent(i)
                for neighbor in self.adj_list[i]:
                    if self.find_parent(neighbor) == -1:
                        self.union_by_height(i, neighbor)
            for neighbor in self.adj_list[i]:
                if self.union_by_height(i, neighbor):
                    Mst_Found = True

            if not Mst_Found:
                self.min_cost += i


