        x1, y1, x2, y2 = area[0]
        merge(i, i+1)

count = 0
for _ in range(q):
    x1, y1, x2, y2 = map(int, input().split())
    count += is_defended(board, x1, y1, x2, y2)
if count == q:
    print("YES")
else:
    print("NO")
