def check_areas(n, m, str_cos, rook_coords, strategic_cells):
    vertical_positions = set(rook_coords.values())

    for start_x, end_x, start_y, end_y in strategic_cells:
        covered = False
        for x in range(start_x, end_x + 1):
            for y in range(start_y, end_y + 1):
                if (x, y) in rook_coords and x not in vertical_positions:
                    covered = True
                    break
            if covered:
                break

        if not covered:
            return "NO"

    return "YES"

