import math

def expected_presidents(n):
    if n == 1:
        return 1.0
    elif n == 2:
        return 2.0

    # The expected number of presidents can be calculated using the expected value formula
    # E[X] = (n * ((n-1)/n + 1)) / 2
    expected_pres = (n * ((n-1)/n + 1)) / 2
    return round(expected_pres, 6)

