def LCA(root, u, v):
    if root <= u and root <= v:
        return root
    elif root >= u and root >= v:
        return root
    mid = (u + v) // 2
    left, right = mid - u, v - mid
    if left == right and root >= left:
        return root
    if left == 0:
        return LCA(root, mid + 1, v)
    if right > left:
        return LCA(root, u, mid)
    return LCA(root, u, mid)

import sys
